            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
            font-size: 24px;
        }

        .feature-card h3 {
            font-size: 20px;
            font-weight: 700;
            color: var(--black);
            margin-bottom: 8px;
        }

        .feature-card p {
            font-size: 15px;
            color: var(--gray-500);
        }

        /* Stats Section */
        .stats {
            background: linear-gradient(135deg, var(--green), var(--purple));
            padding: 80px 40px;
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 40px;
            max-width: 1000px;
            margin: 0 auto;
            text-align: center;
        }

        .stat-item h3 {
            font-size: clamp(48px, 6vw, 72px);
            font-weight: 800;
            color: var(--white);
            line-height: 1;
            margin-bottom: 8px;
        }

        .stat-item p {
            font-size: 16px;
            color: rgba(255, 255, 255, 0.8);
            font-weight: 500;
        }

        /* Courses Section */
        .courses {
            padding: 100px 40px;
            background: var(--gray-100);
        }

        .course-tabs {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
            justify-content: center;
            margin-bottom: 48px;
            max-width: 1200px;
            margin-left: auto;
            margin-right: auto;
