            overflow: hidden;
        }

        .course-instructor {
            font-size: 14px;
            color: var(--gray-500);
            margin-bottom: 12px;
        }

        .course-meta {
            display: flex;
            gap: 16px;
            font-size: 13px;
            color: var(--gray-500);
        }

        .course-meta span {
            display: flex;
            align-items: center;
            gap: 4px;
        }

        /* Creative Feed Section */
        .creative-feed {
            padding: 100px 40px;
            background: var(--white);
        }

        .feed-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 24px;
            max-width: 1200px;
            margin: 0 auto;
        }

        .feed-card {
            padding: 40px;
            background: linear-gradient(135deg, #0a0a0a 0%, #1a1a2e 100%);
            border-radius: 20px;
            color: var(--white);
            transition: transform 0.2s;
        }

        .feed-card:hover {
            transform: scale(1.02);
        }

        .feed-card h3 {
            font-size: 24px;
            font-weight: 700;
            margin-bottom: 12px;
        }

        .feed-card p {
            font-size: 15px;
            color: var(--gray-300);
            line-height: 1.6;
        }

        .feed-icon {
            width: 48px;
            height: 48px;
            background: linear-gradient(135deg, var(--green), var(--purple));
            border-radius: 12px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 20px;
            font-size: 20px;
        }

        /* Teachers Section */
        .teachers {
            padding: 100px 40px;
            background: var(--gray-100);
        }

        .teachers-carousel {
            max-width: 1200px;
            margin: 0 auto;
            position: relative;
        }

        .teachers-track {
            display: flex;
            gap: 24px;
            overflow-x: auto;
            scroll-behavior: smooth;
            scrollbar-width: none;
            -ms-overflow-style: none;
            padding: 20px 0;
        }

        .teachers-track::-webkit-scrollbar {
            display: none;
        }

        .teacher-card {
            flex: 0 0 280px;
            background: var(--white);
            border-radius: 20px;
            padding: 32px;
            text-align: center;
            transition: transform 0.2s, box-shadow 0.2s;
        }

        .teacher-card:hover {
            transform: translateY(-4px);
            box-shadow: 0 12px 40px rgba(0, 0, 0, 0.1);
        }

        .teacher-avatar {
            width: 100px;
            height: 100px;
            border-radius: 50%;
            background: linear-gradient(135deg, var(--green), var(--purple));
            margin: 0 auto 20px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 36px;
            font-weight: 700;
            color: var(--white);
        }

        .teacher-card h3 {
            font-size: 18px;
            font-weight: 700;
            color: var(--black);
            margin-bottom: 4px;
        }

        .teacher-card p {
            font-size: 14px;
            color: var(--gray-500);
        }

        .carousel-nav {
            display: flex;
            gap: 12px;
            justify-content: center;
            margin-top: 32px;
        }

        .carousel-btn {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            border: 2px solid var(--gray-300);
            background: var(--white);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: all 0.2s;
        }

        .carousel-btn:hover {
            border-color: var(--black);
            background: var(--black);
            color: var(--white);
