        /* Testimonials Section */
        .testimonials {
            padding: 100px 40px;
            background: var(--white);
        }

        .testimonials-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 24px;
            max-width: 1200px;
            margin: 0 auto;
        }

        .testimonial-card {
            background: var(--gray-100);
            border-radius: 20px;
            padding: 32px;
        }

        .testimonial-quote {
            font-size: 16px;
