        /* Teams Section */
        .teams {
            padding: 100px 40px;
            background: linear-gradient(135deg, #0a0a0a 0%, #1a1a2e 100%);
            text-align: center;
        }

        .teams h2 {
            font-size: clamp(32px, 4vw, 48px);
            font-weight: 800;
            color: var(--white);
            margin-bottom: 20px;
        }

        .teams p {
            font-size: 18px;
            color: var(--gray-300);
            max-width: 600px;
            margin: 0 auto 40px;
            line-height: 1.7;
        }

        .btn-teams {
            display: inline-block;
            padding: 16px 40px;
            background: linear-gradient(135deg, var(--green), var(--purple));
            color: var(--white);
            text-decoration: none;
            border-radius: 100px;
            font-weight: 700;
            font-size: 16px;
            transition: transform 0.2s, box-shadow 0.2s;
        }

        .btn-teams:hover {
            transform: translateY(-2px);
            box-shadow: 0 8px 24px rgba(85, 218, 155, 0.3);
        }

        /* FAQ Section */
        .faq {
            padding: 100px 40px;
            background: var(--gray-100);
        }

        .faq-list {
            max-width: 800px;
            margin: 0 auto;
        }

        .faq-item {
            background: var(--white);
            border-radius: 16px;
            margin-bottom: 12px;
            overflow: hidden;
        }

        .faq-question {
            width: 100%;
            padding: 24px;
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: none;
            border: none;
            cursor: pointer;
            font-size: 16px;
            font-weight: 600;
            color: var(--black);
            text-align: left;
            font-family: inherit;
        }

        .faq-question:hover {
            color: var(--gray-700);
        }

        .faq-icon {
            width: 24px;
            height: 24px;
            position: relative;
            flex-shrink: 0;
        }

        .faq-icon::before,
        .faq-icon::after {
            content: '';
            position: absolute;
            background: var(--gray-500);
            transition: transform 0.3s;
        }

        .faq-icon::before {
            width: 100%;
            height: 2px;
            top: 50%;
            left: 0;
            transform: translateY(-50%);
        }

        .faq-icon::after {
            width: 2px;
            height: 100%;
            left: 50%;
            top: 0;
            transform: translateX(-50%);
        }

        .faq-item.open .faq-icon::after {
            transform: translateX(-50%) rotate(90deg);
        }

        .faq-answer {
            max-height: 0;
            overflow: hidden;
            transition: max-height 0.3s ease-out;
        }

        .faq-answer-inner {
            padding: 0 24px 24px;
            font-size: 15px;
            color: var(--gray-500);
            line-height: 1.7;
        }

        .faq-item.open .faq-answer {
            max-height: 500px;
        }

        /* Footer */
        footer {
            background: var(--black);
            color: var(--white);
