            text-align: center;
        }

        .footer-legal {
            font-size: 12px;
            color: var(--gray-500);
            margin-bottom: 16px;
        }

        .footer-copyright {
            font-size: 14px;
            color: var(--gray-500);
        }

        /* Responsive */
        @media (max-width: 768px) {
            nav {
                padding: 0 20px;
            }

            .nav-links {
                display: none;
            }

            .hero {
                padding: 120px 20px 60px;
            }

            .stats-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .features, .courses, .creative-feed, .teachers, .testimonials, .faq {
                padding: 60px 20px;
            }

            .course-tabs {
                justify-content: flex-start;
                overflow-x: auto;
                flex-wrap: nowrap;
                padding-bottom: 12px;
            }

            .course-tab {
                flex-shrink: 0;
            }

            footer {
                padding: 60px 20px 30px;
            }

            .footer-grid {
                grid-template-columns: repeat(2, 1fr);
            }
        }
    </style>
</head>
<body>
    <nav>
        <a href="#" class="nav-logo"><span>CreativeHub</span></a>
